r.append(R(7733710,"मैक्सिकन टूना पाटे",
"एक बहुमुखी और आसान स्प्रेड जो नाश्ते के लिए अच्छा है या पार्टी के नमकीन के रूप में बढ़िया।",
"2","206 ग्राम",
["160 ग्राम का स्प्रिंग वॉटर में डिब्बाबंद टूना, पानी निथारा हुआ","1 छोटा चम्मच हल्का मिर्च पाउडर (यदि पसंद हो तो तीखा)","1 छोटा चम्मच जीरा","1 छोटा चम्मच सूखा ओरेगानो","1 बड़ा चम्मच टमाटर प्यूरी","3 हरे प्याज़, बारीक कटे हुए","आधी लाल शिमला मिर्च, बारीक कटी हुई","1 बड़ा ताज़ा टमाटर, बारीक कटा हुआ","1 बड़ा चम्मच बारीक कटा ताज़ा धनिया","1 नींबू (लाइम) का रस","2 बड़े चम्मच 0% ग्रीक योगर्ट"],
["टूना को एक कटोरे में रखें, योगर्ट को छोड़कर सारी सामग्री डालें और अच्छी तरह मिलाएँ।","योगर्ट मिलाएँ और फिर से मिलाएँ।","टॉर्टिला और सलाद के साथ परोसें।"],
["पाटे को साबुत गेहूँ के टॉर्टिला पर फैलाएँ, सिगार के आकार में लपेटें और कॉकटेल स्टिक से जमा दें, फिर गोल टुकड़ों में काटें – एक सरल पार्टी नमकीन के लिए आदर्श।","वैकल्पिक रूप से, मैक्सिकन शैली के कैनपे के लिए एक छोटा चम्मच टॉर्टिला चिप पर रखें। (परोसने से ठीक पहले चिप्स पर डालें ताकि वे कुरकुरे रहें)।",FV(1)]))
r.append(R(7733869,"क्रीम फ्रेश के साथ गरम सूफ़्ले सेब",
"जायफल इस फलों वाली खाने के बाद की मिठाई को उसका नाज़ुक स्वाद देता है।",
"2","142 ग्राम",
["2 खाने वाले सेब","एक बूँद नींबू का रस","1 छोटा चम्मच मक्खन","एक चुटकी पिसा जायफल","25 ग्राम बारीक चीनी","1 मध्यम अंडा, सफ़ेदी और ज़र्दी अलग की हुई",["परोसने के लिए","2 बड़े चम्मच कम वसा वाला क्रीम फ्रेश"],["परोसने के लिए","एक चुटकी पिसा जायफल"]],
["ओवन को 190ºC/गैस 5 पर पहले से गरम करें। सेबों का निचला सिरा काट दें, फिर हर एक के ऊपरी किनारे के चारों ओर काटें और गूदा निकाल लें, लगभग ½ सेमी का किनारा छोड़ते हुए। कटे हुए किनारों पर नींबू का रस लगाएँ।","सेब के गूदे को मोटा काटें और 1 बड़े चम्मच पानी के साथ पैन में रखें। ढककर 5-6 मिनट तक या नरम होने तक धीमी आँच पर पकाएँ, फिर छन्नी से दबाकर छान लें।","मक्खन, जायफल, चीनी और अंडे की ज़र्दी को सेब में फेंटकर मिलाएँ। इस बीच, अंडे की सफ़ेदी को तब तक फेंटें जब तक कि वह कड़े शिखर न बना ले। इसे सावधानी से सेब के मिश्रण में मिलाएँ।","सूफ़्ले के मिश्रण को सेबों में चम्मच से भरें, बेकिंग ट्रे पर रखें और 20-25 मिनट तक सुनहरा होने और फूलने तक बेक करें। क्रीम फ्रेश और ऊपर से थोड़ा और जायफल छिड़ककर परोसें।"],
["आप जायफल की जगह पिसी दालचीनी या अदरक का उपयोग कर सकते हैं।"]))
r.append(R(7735462,"पटाटास ब्रावास",
"तीखे टमाटर सॉस में आलू के टुकड़े। 'ब्रावास' का मतलब बहादुर है, जो उनके तीखेपन की ओर इशारा करता है।",
"8","167 ग्राम",
["2 बड़े चम्मच जैतून का तेल","1 बड़ा प्याज़, कटा हुआ","2 फांक लहसुन, कुचला हुआ","2 छोटे चम्मच स्मोक्ड पेपरिका","2 बड़े टमाटर, कटे हुए या 200 ग्राम का डिब्बा कटे हुए टमाटर","150 मिली वेजिटेबल स्टॉक","750 ग्राम आलू, टुकड़ों में कटे हुए","ताज़ा पिसी हुई काली मिर्च"],
["एक नॉन-स्टिक पैन में आधा तेल गरम करें, प्याज़ और लहसुन डालें और 4-5 मिनट तक नरम होने तक भूनें।","पेपरिका, टमाटर और स्टॉक डालें, उबाल आने दें और 15 मिनट तक धीमी आँच पर पकाएँ। भरपूर काली मिर्च डालें, ब्लेंडर या फ़ूड प्रोसेसर में डालें और चिकना होने तक ब्लेंड करें।","इस बीच, आलू को उबलते पानी में 7-8 मिनट तक बस नरम होने तक पकाएँ।","पानी निथारें और बचे हुए तेल में मिलाएँ। बेकिंग शीट पर रखें और तेज़ ग्रिल के नीचे 5-6 मिनट तक चारों ओर से सुनहरा भूरा होने तक पकाएँ।","आलू को टमाटर सॉस के साथ परोसें।"],
["स्मोक्ड पेपरिका व्यंजनों में अद्भुत स्वाद जोड़ती है, आप हल्की (डल्स) या तीखी (पिकांते) ले सकते हैं, यह इस पर निर्भर करता है कि आप कितने 'ब्रावास' (बहादुर) हैं!","अक्सर तापास के रूप में परोसे जाने वाले ये आलू ग्रिल किए हुए सैल्मन या टूना के टुकड़े और सलाद के साथ परोसने पर एक बढ़िया साइड डिश हैं।",FZ+"फ्रिज में या माइक्रोवेव में पिघलाएँ और पूरी तरह गरम होने तक दोबारा गरम करें।",FV(0)]))
r.append(R(7737810,"मसालेदार टोफू स्क्रैम्बल",
"यह ट्रेंडी व्यंजन वीगन लोगों को उनका अपना स्क्रैम्बल्ड एग वाला संस्करण देने के लिए बनाया गया था, लेकिन हमारा मानना है कि यह इतना अच्छा है कि हर किसी को इसे आज़माना चाहिए। यह रेसिपी स्लिमिंग वर्ल्ड के साथ साझेदारी में चुनी गई है।",
"4","447 ग्राम",
["2 छोटे चम्मच मध्यम करी पाउडर","1 छोटा चम्मच जीरा (साबुत)","1 छोटा चम्मच काली सरसों के दाने","1 छोटा चम्मच पिसी हल्दी","कम कैलोरी वाला कुकिंग स्प्रे","500 ग्राम बेबी बटन मशरूम, आधे कटे हुए या स्लाइस किए हुए","3 शिमला मिर्च (किसी भी रंग की), बीज निकालकर मोटी कटी हुई","6 हरे प्याज़, कटे हुए","1 सेमी ताज़ा अदरक की जड़ का टुकड़ा, छिला और कद्दूकस किया हुआ","2 फांक लहसुन, बारीक कटा हुआ","1 लाल मिर्च, बीज निकालकर बारीक कटी हुई","2 x 350 ग्राम के पैकेट सादा सिल्कन टोफू","परोसने के लिए कटा हुआ ताज़ा सोआ (डिल)"],
["सारे मसाले एक कटोरे में डालें और अच्छी तरह मिलाएँ।","एक बड़े नॉन-स्टिक फ्राइंग पैन पर कम कैलोरी वाले कुकिंग स्प्रे के दो-तीन पंप छिड़कें और उसे मध्यम-तेज़ आँच पर रखें। मशरूम, शिमला मिर्च, हरे प्याज़, अदरक, लहसुन और मिर्च डालें और लगभग 8 मिनट तक भूनें, या जब तक सब कुछ बस भूरा होना शुरू न हो जाए।","उँगलियों से टोफू को क्रम्बल करके डालें ताकि 'स्क्रैम्बल्ड एग' जैसी अच्छी बनावट आए। मसाले का मिश्रण मिलाएँ और 6-8 मिनट और स्टिर-फ्राई करें।","स्वादानुसार काली मिर्च डालें और परोसने के लिए ऊपर से सोआ बिखेर दें।"],
["मसाले/सीज़निंग मिश्रणों में चीनी, नमक, आटा या तेल जैसी अतिरिक्त सामग्री हो सकती है, इसलिए उन्हें जाँच लें। यदि संभव हो तो केवल जड़ी-बूटियों और मसालों से बने मिश्रण चुनें।","स्लिमिंग वर्ल्ड के साथ हमारी साझेदारी के बारे में और जानें।",FV(3)]))
r.append(R(7739965,"बैंग बैंग चिकन सलाद",
"रसीले चिकन और ताज़गी भरे सलाद का एक झटपट और सरल व्यंजन।",
"2","498 ग्राम",
["2 चिकन ब्रेस्ट फ़िलेट (200 ग्राम)","1 छोटा चम्मच रेपसीड तेल","1 प्याज़, बारीक कटा हुआ","1 लाल मिर्च, बारीक कटी हुई","3 फांक लहसुन, कुचला हुआ","4 सेमी अदरक, बारीक कटा हुआ","2 बड़े चम्मच पानी","2 छोटे चम्मच पीनट बटर","2 छोटे चम्मच शहद","2 छोटे चम्मच तिल का तेल",["सलाद के लिए","4 हरे प्याज़, माचिस की तीलियों जैसे कटे हुए"],["सलाद के लिए","2 गाजर, सब्ज़ी छीलने वाले छीलक से रिबन की तरह छीली हुई"],["सलाद के लिए","100 ग्राम खीरा, छोटी तीलियों में कटा हुआ"],["सलाद के लिए","100 ग्राम लेट्यूस की पत्तियाँ, छोटे टुकड़ों में फाड़ी हुई"],["सलाद के लिए","2 छोटे चम्मच कम नमक वाला सोया सॉस"],["सलाद के लिए","1 नींबू (लाइम) का छिलका और रस, परोसने के लिए फाँकें अलग"],["सलाद के लिए","25 ग्राम ताज़ा धनिया"]],
["चिकन को उबलते पानी के एक छोटे पैन में डालें। फिर से उबाल आने दें, आँच धीमी करें और अंदर तक पकने के लिए 10 मिनट तक पकाएँ। आँच से उतारें और 5 मिनट के लिए पानी में ही छोड़ दें।","सलाद के लिए, हरे प्याज़ को 3 सेमी के टुकड़ों में काटें और फिर उन्हें लंबाई में काटकर माचिस की तीलियों जैसा बना लें। सलाद की बाक़ी सारी सामग्री तैयार करें, सब कुछ मिलाएँ और अलग रख दें।","एक छोटे सॉसपैन में तेल डालें, फिर प्याज़ डालें और 3-4 मिनट पकाएँ। इसके बाद मिर्च, लहसुन और अदरक डालें और 1 मिनट चलाएँ। पानी, शहद, पीनट बटर और तिल का तेल डालें और तब तक चलाएँ जब तक सब कुछ घुल न जाए।","चिकन को छोटे, पतले टुकड़ों में काटें और सॉस में डालकर अच्छी तरह लपेटने के लिए मिलाएँ।","सलाद को प्लेट पर रखें और चिकन को बाहर की तरफ़ सजाएँ। नींबू (लाइम) की फाँकों के साथ परोसें।"],
["यह व्यंजन चिकन की जगह पके हुए झींगे या सूअर के मांस के साथ भी उतना ही अच्छा लगता है।","शाकाहारी विकल्प के लिए मैरिनेट किए हुए टोफू का उपयोग करके देखें।","इस सलाद को ग्लूटेन-मुक्त बनाने के लिए, आपको बस सोया सॉस की जगह ग्लूटेन-मुक्त तामारी का उपयोग करना है।",FV(3)]))
r.append(R(7741982,"मसालेदार झींगा और पाक चोई स्टिर-फ्राई",
"हल्की मिर्च और लहसुन वाली स्टिर-फ्राई जो स्वाद से भरपूर है।",
"2","331 ग्राम",
["1 प्याज़, पतला कटा हुआ","1 लाल शिमला मिर्च, पतली कटी हुई","4 चेस्टनट मशरूम, कटे हुए","2 फांक लहसुन, कुचला हुआ","आधी लाल मिर्च, कटी हुई (या एक चुटकी मिर्च के फ्लेक्स)","1 बड़ा चम्मच रेपसीड तेल","150 ग्राम कच्चे किंग प्रॉन (बड़े झींगे)","2 छोटे चम्मच कम नमक वाला सोया सॉस","1 ढेर वाला छोटा चम्मच चाइनीज़ फ़ाइव-स्पाइस","2 पाक चोई, पत्तियाँ साबुत और डंठल कटे हुए","2 बड़े चम्मच पानी"],
["प्याज़, लाल शिमला मिर्च, चेस्टनट मशरूम, लहसुन और लाल मिर्च तैयार करें और अलग रख दें।","कड़ाही या बड़े फ्राइंग पैन को तेज़ आँच पर गरम करें, रेपसीड तेल डालें और जब गरम हो जाए तो प्याज़ डालें। 2 मिनट स्टिर-फ्राई करें, फिर लाल शिमला मिर्च, मशरूम, लहसुन और मिर्च डालें और 1 मिनट स्टिर-फ्राई करें।","झींगे, सोया सॉस, चाइनीज़ फ़ाइव-स्पाइस और पाक चोई के डंठल डालें, और झींगे के पकने तक 3–4 मिनट और चलाते रहें। पकने पर झींगे का गूदा गुलाबी या नारंगी हो जाना चाहिए और उसकी पारभासी दिखावट ख़त्म हो जानी चाहिए।","पाक चोई की पत्तियाँ और पानी डालें, ढक्कन से ढकें और 1 मिनट और पकाएँ। अच्छी तरह मिलाएँ और तुरंत परोसें।","नूडल्स के साथ या लाल मिर्च के कुछ पतले स्लाइस और नींबू (लाइम) की एक फाँक के साथ परोसें।"],
["पहले सामग्री को इकट्ठा कर लें, ताकि उन्हें पैन में डालने के लिए तैयार रखा जा सके। और हमेशा सुनिश्चित करें कि उन्हें डालना शुरू करने से पहले पैन वाकई गरम हो।","स्टिर-फ्राई करना पकाने का एक तेज़ तरीक़ा है और इसमें आपके भोजन में अधिक पोषक तत्व बचे रहते हैं। आपको ज़्यादा तेल की ज़रूरत नहीं होती और जब तक आप पैन में चलाते रहते हैं, खाना तलने की जगह भाप में पकता है।",FV(3)]))
r.append(R(7742200,"कद्दू और चिकन करी",
"रसीली चिकन थाई और स्वादिष्ट रूप से कैरामेलाइज़्ड बटरनट स्क्वैश का मेल एक मुँह में पानी लाने वाली करी बनाता है जिसे आप बार-बार बनाना चाहेंगे। यह रेसिपी स्लिमिंग वर्ल्ड के साथ साझेदारी में चुनी गई थी।",
"4","574 ग्राम",
["1 बटरनट स्क्वैश, आधा कटा, बीज निकाले हुए और फाँकों में कटा हुआ","कम कैलोरी वाला कुकिंग स्प्रे","1 लाल प्याज़, बारीक कटा हुआ","1 बड़ा चम्मच सूखा गरम मसाला (रेसिपी टिप देखें)","1/2 छोटा चम्मच हल्का मिर्च पाउडर","3 फांक लहसुन, कुचला हुआ","3 सेमी ताज़ा अदरक की जड़ का टुकड़ा, छिला और बारीक कद्दूकस किया हुआ","2 x 400 ग्राम के डिब्बे कटे हुए टमाटर","400 मिली पानी","500 ग्राम बिना त्वचा और बिना हड्डी की चिकन थाई, दिखने वाली चर्बी हटाई हुई, टुकड़ों में कटी हुई","परोसने के लिए ताज़ी धनिया की पत्तियाँ"],
["ओवन को 200°C/फ़ैन 180°C/गैस 6 पर पहले से गरम करें। स्क्वैश को कम कैलोरी वाले कुकिंग स्प्रे के दो-तीन पंप के साथ 1 या 2 नॉन-स्टिक बेकिंग ट्रे पर एक परत में फैलाएँ। 40-45 मिनट तक या सुनहरा और कैरामेलाइज़्ड होने तक रोस्ट करें, बीच में पलट दें।","इस बीच, एक नॉन-स्टिक सॉसपैन पर कम कैलोरी वाले कुकिंग स्प्रे के दो-तीन पंप छिड़कें और मध्यम आँच पर रखें। प्याज़ को 5-6 मिनट तक भूनें। गरम मसाला, मिर्च पाउडर, लहसुन और अदरक को थोड़े पानी के साथ डालें और 2-3 मिनट पकाएँ। टमाटर और एक डिब्बे जितना पानी डालें और उबाल तक लाएँ।","चिकन को पैन में डालें और अंदर तक पकने और कोई गुलाबी मांस न दिखने तक 15-20 मिनट धीमी आँच पर पकाएँ (चिकन के सबसे मोटे हिस्से को काटने पर रस साफ़ निकलना चाहिए)।","स्क्वैश को करी में मिलाएँ और काली मिर्च से स्वाद बनाएँ। ऊपर से धनिया बिखेरें और परोसें।"],
["मसाले/सीज़निंग मिश्रणों में चीनी, नमक, आटा या तेल जैसी अतिरिक्त सामग्री हो सकती है, इसलिए उन्हें जाँच लें। यदि संभव हो तो केवल जड़ी-बूटियों और मसालों से बने मिश्रण चुनें।",FV(3)]))
r.append(R(7743074,"बीफ़ और हॉर्सरैडिश के साथ छोटे बेक्ड आलू",
"ये पार्टी के लिए या नाश्ते के रूप में बढ़िया हैं और आप पोच किए या डिब्बाबंद सैल्मन से लेकर भुने हुए मशरूम या पालक और बकरी के चीज़ तक हर तरह की भरावन डाल सकते हैं।",
"10","64 ग्राम",
["12 छोटे आलू (लगभग 500 ग्राम)","4 बड़े चम्मच फ़ैट-फ़्री फ्रोमाज फ्रे","2 बड़े चम्मच हॉर्सरैडिश सॉस","1 बड़ा चम्मच ताज़ा चाइव्स, कटे हुए","2 पतले स्लाइस पका हुआ रोस्ट बीफ़ (लगभग 50 ग्राम)","ताज़ा पिसी हुई काली मिर्च"],
["ओवन को 200ºC/गैस मार्क 6 पर पहले से गरम करें। हर आलू की त्वचा में कई बार छेद करें और बेकिंग शीट पर रखें। अंदर तक पकने के लिए 35-40 मिनट तक बेक करें।","फ्रोमाज फ्रे और हॉर्सरैडिश को मिलाएँ।","तेज़ चाकू से हर आलू के ऊपर चीरा लगाएँ और उसे खोलने के लिए दबाएँ।","हर आलू में फ्रोमाज फ्रे और हॉर्सरैडिश का थोड़ा मिश्रण चम्मच से भरें। हर एक के ऊपर थोड़ा बीफ़ रखें, चाइव्स छिड़कें और परोसें।"],
["आलू के आकार के आधार पर आप इन्हें कैनपे के आकार का या काफ़ी भारी-भरकम बना सकते हैं।","यदि आप पार्टी कर रहे हैं, तो आलू बेक करें और अपनी सारी भरावन तैयार कर लें, फिर आलू को ज़रूरत से 10 मिनट पहले ओवन में रखें, भरें और परोसें।","आप सभी तरह की भरावन के साथ प्रयोग कर सकते हैं - पोच किए/डिब्बाबंद सैल्मन से लेकर भुने हुए मशरूम, या पालक और बकरी के चीज़ तक।",FV(0)]))
r.append(R(7746605,"पॉपकॉर्न",
"बच्चों के साथ बनाने में मज़ेदार, यह दुकान से खरीदे गए पॉपकॉर्न का ज़्यादा सेहतमंद और सस्ता विकल्प है।",
"10","15 ग्राम",
["75 ग्राम पॉपिंग कॉर्न (मक्के के दाने)","1 संतरे का रस और छिलका","1 सपाट छोटा चम्मच अदरक पाउडर (सोंठ)","3 छोटे चम्मच दानेदार स्वीटनर"],
["ढक्कन वाला एक बड़ा गहरा पैन गरम करें, उसमें पॉपिंग कॉर्न का आधा (या एक-तिहाई, आपके पैन के आकार पर निर्भर) डालें और ढक दें। नियमित रूप से हिलाएँ और 2-3 मिनट बाद आपको मक्के के फूटने की आवाज़ आने लगेगी – ढक्कन खोलने के लालच में न पड़ें! फूटना बंद होने तक हिलाते रहें।","फूले हुए मक्के को एक बड़े कटोरे में डालें और जो दाने न फूटे हों उन्हें फेंक दें। जब तक सारा मक्का न हो जाए, इसे दोहराते रहें।","इस बीच, एक दूसरे सॉसपैन में संतरे का रस, अदरक और स्वीटनर को घुलने तक गरम करें। तब तक मिलाएँ जब तक उबाल न आ जाए, फिर 2-3 मिनट तक गरम करें जब तक कि वह चिपचिपा न हो जाए और मात्रा तीन-चौथाई कम न हो जाए।","छिलका मिलाएँ और पॉपकॉर्न डालें, अच्छी तरह मिलाएँ ताकि सब पर लग जाए।","इसे ट्रे पर फैलाएँ और बैग में भरने से पहले पूरी तरह सूखने दें।"],
["एक साथ बहुत ज़्यादा मक्का न डालें – खेपों में पकाएँ क्योंकि यह बहुत फूलता है। फूटते समय ढक्कन न खोलें क्योंकि यह पूरी रसोई में बिखर जाएगा।","ध्यान रखें कि पैन पूरी तरह सूख न जाए क्योंकि आपको पॉपकॉर्न पर लपेटने के लिए पर्याप्त सॉस चाहिए, लेकिन यदि सॉस बहुत गीला हुआ तो आपका पॉपकॉर्न गीला हो जाएगा।","बैग में भरने से पहले सुनिश्चित करें कि पॉपकॉर्न पूरी तरह ठंडा हो गया है।","एक अच्छी चुटकी मसाला, जैसे दालचीनी या जायफल, डालकर देखें।","यदि आप इस चिपचिपे संतरे और अदरक वाले पॉपकॉर्न को बैग में भरकर रिबन से बाँध दें, तो यह हैलोवीन के लिए एक सेहतमंद उपहार है।",FV(0)]))
r.append(R(7748136,"पोर्टोबेलो मशरूम बर्गर",
"ये नम मशरूम बर्गर पालक और क्रीम चीज़ से सजे होते हैं और बारबेक्यू या ग्रिडल करने पर बेहतरीन स्वाद देते हैं।",
"4","374 ग्राम",
["4 बड़े पोर्टोबेलो मशरूम","2 छोटे चम्मच रेपसीड तेल","1 प्याज़, बारीक कटा हुआ","300 ग्राम जमा हुआ पालक, पिघलाया हुआ","एक अच्छी पिसाई काली मिर्च","एक अच्छी चुटकी जायफल","50 ग्राम कम वसा वाला लहसुन और जड़ी-बूटियों वाला क्रीम चीज़","4 बीज वाले साबुत गेहूँ के रोल","100 ग्राम लेट्यूस","2 टमाटर, पतले कटे हुए","1 लाल प्याज़, पतला कटा हुआ"],
["मशरूम के डंठल निकालें और बारीक काट लें।","एक फ्राइंग पैन में तेल डालें और प्याज़ और कटे हुए मशरूम के डंठलों को 4-5 मिनट तक भूरा होने तक पकाएँ, फिर ठंडा होने दें।","इस बीच, पालक से अतिरिक्त पानी निचोड़ लें और एक कटोरे में रखें।","प्याज़ और पालक को भरपूर काली मिर्च और जायफल के साथ मिलाएँ। क्रीम चीज़ मिलाएँ, अच्छी तरह मिलाकर 4 बराबर आकार के गोले बना लें।","इस बीच, मशरूम के गिल वाले हिस्से (अंदर की तरफ़) को ग्रिल या ग्रिडल करें, फिर हर एक के ऊपर पालक का मिश्रण रखें। ग्रिल या बारबेक्यू करने के लिए तैयार होने तक अलग रख दें।","मशरूम को बारबेक्यू या ग्रिडल पैन पर रखें, गरमी रोकने के लिए ऊपर से किचन फ़ॉइल का एक टुकड़ा ढीला-सा रख दें, ताकि धुएँ का स्वाद सोख लिया जाए। 4-5 मिनट तक पकाएँ।","बन को हल्का टोस्ट करें और मशरूम को लेट्यूस, कटे टमाटर और लाल प्याज़ के साथ लगाएँ।"],
["आप बारबेक्यू की जगह मशरूम को मध्यम गरम ओवन में 10-15 मिनट तक पका सकते हैं।","छोटे मशरूम और बन का उपयोग करके मिनी संस्करण बनाने की कोशिश करें, ये पार्टी के लिए बढ़िया हैं।",FV(3)]))
save(7,r)
